Write a C# program that stores 5 words in an array.
After storing the words, ask the user to enter a search word.
If the word exists in the array, display:
True
Otherwise display:
False

Requirements:
1. Read 5 words from the user.
2. Store the words in an array.
3. Read a search word.
4. Search the array for the word.
5. Display True if the word exists.
6. Display False if the word does not exist.
7. Stop searching once the word is found.


سلم التصحيح:
Total: 10 marks

1. Read words correctly: 2 marks
2. Store words in array: 2 marks
3. Read search word: 1 mark
4. Search logic: 3 marks
5. Correct output: 1 mark
6. Code readability: 1 mark

الحل النموذجي:
using System;

class Program
{
    static void Main()
    {
        string[] words = new string[5];

        for (int i = 0; i < 5; i++)
        {
            words[i] = Console.ReadLine();
        }

        string searchWord = Console.ReadLine();

        bool found = false;

        for (int i = 0; i < 5; i++)
        {
            if (words[i] == searchWord)
            {
                found = true;
                break;
            }
        }

        Console.WriteLine(found);
    }
}

حل الطالب:
﻿// Correct solution.
// Uses while loop.

using System;

class Program
{
    static void Main()
    {
        string[] words = new string[5];

        int i = 0;

        while (i < 5)
        {
            words[i] = Console.ReadLine();
            i++;
        }

        string searchWord = Console.ReadLine();

        bool found = false;
        i = 0;

        while (i < 5)
        {
            if (words[i] == searchWord)
            {
                found = true;
                break;
            }

            i++;
        }

        Console.WriteLine(found);
    }
}

