Title: Shopping Cart System

Problem Statement: 
Write a JavaScript program that calculates the final bill for a shopping cart.
The program should:
1. Read prices of 5 products.
2. Calculate the subtotal.
3. If the subtotal is greater than or equal to 100, apply a 10% discount.
4. Calculate the final total after discount.
5. Display:
   - Subtotal
   - Discount
   - Final Total

Requirements:
1. Read 5 product prices.
2. Calculate subtotal correctly.
3. Apply 10% discount only when subtotal >= 100.
4. Calculate final total correctly.
5. Display subtotal.
6. Display discount.
7. Display final total.

سلم التصحيح:
Total: 10 marks

1. Input reading: 2 marks
2. Subtotal calculation: 3 marks
3. Discount calculation: 2 marks
4. Final total calculation: 1 mark
5. Correct output: 1 mark
6. Code readability: 1 mark

الحل النموذجي:
const readline = require("readline");

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let prices = [];
let count = 0;

function readPrice() {
    rl.question("Price " + (count + 1) + ": ", (price) => {
        prices.push(parseFloat(price));
        count++;

        if (count < 5) {
            readPrice();
        } else {
            let subtotal = 0;

            for (let price of prices) {
                subtotal += price;
            }

            let discount = 0;

            if (subtotal >= 100) {
                discount = subtotal * 0.10;
            }

            let finalTotal = subtotal - discount;

            console.log("Subtotal:", subtotal);
            console.log("Discount:", discount);
            console.log("Final Total:", finalTotal);

            rl.close();
        }
    });
}

readPrice();

