Title: Online Exam System

Problem Statement: 
Write a JavaScript program that reads the grades of 5 exams.
The program should:
1. Store the grades in an array.
2. Calculate the average grade.
3. Determine if the student passed or failed.
Rules:
- If average >= 60 → Pass
- Otherwise → Fail
Display:
- Average Grade
- Result

Requirements:
1. Read 5 grades.
2. Store grades in an array.
3. Calculate the average correctly.
4. Determine Pass/Fail correctly.
5. Display average.
6. Display result.

سلم التصحيح:
Total: 10 marks

1. Input reading: 2 marks
2. Array usage: 1 mark
3. Average calculation: 3 marks
4. Pass/Fail logic: 2 marks
5. Correct output: 1 mark
6. Code readability: 1 mark

الحل النموذجي:
const readline = require("readline");

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let grades = [];
let count = 0;

function readGrade() {
    rl.question("Grade: ", (grade) => {

        grades.push(Number(grade));
        count++;

        if (count < 5) {
            readGrade();
        }
        else {

            let sum = 0;

            for (let grade of grades) {
                sum += grade;
            }

            let average = sum / grades.length;

            console.log("Average:", average);

            if (average >= 60) {
                console.log("Result: Pass");
            }
            else {
                console.log("Result: Fail");
            }

            rl.close();
        }
    });
}

readGrade();

