    let upper = false;
    let lower = false;
    let digit = false;

    for (let c of password) {

        if (c >= "A" && c <= "Z")
            upper = true;

        if (c >= "a" && c <= "z")
            lower = true;

        if (c >= "0" && c <= "9")
            digit = true;
    }

    return password.length >= 8 &&
           upper &&
           lower &&
           digit;
}

