Question_ID: Q007

Title: Student GPA Calculator

Problem Statement: 
Write a JavaScript program that calculates a student's GPA.
The program should read the grades of 5 courses.
Each grade is from 0 to 100.
For each course, convert the numeric grade to grade points using the following rules:
- 90 to 100  → 4.0
- 80 to 89   → 3.0
- 70 to 79   → 2.0
- 60 to 69   → 1.0
- Below 60   → 0.0

Then:
1. Store the 5 grades in an array.
2. Convert each grade to grade points.
3. Calculate the GPA as the average of the 5 grade points.
4. Display the GPA.
5. Display the academic standing using:
   - GPA >= 3.5  → Excellent
   - GPA >= 2.5  → Very Good
   - GPA >= 2.0  → Good
   - GPA >= 1.0  → Pass
   - Otherwise   → Fail

Requirements:
1. Read 5 grades.
2. Store grades in an array.
3. Convert each grade to the correct grade points.
4. Calculate GPA correctly.
5. Determine the correct academic standing.
6. Display GPA.
7. Display standing.

سلم التصحيح:
Total: 10 marks

1. Input reading: 2 marks
2. Array usage: 1 mark
3. Grade-to-points conversion: 3 marks
4. GPA calculation: 2 marks
5. Standing determination: 1 mark
6. Correct output: 1 mark

الحل النموذجي:
const readline = require("readline");

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let grades = [];
let count = 0;

function gradeToPoint(grade) {
    if (grade >= 90) {
        return 4.0;
    }
    else if (grade >= 80) {
        return 3.0;
    }
    else if (grade >= 70) {
        return 2.0;
    }
    else if (grade >= 60) {
        return 1.0;
    }
    else {
        return 0.0;
    }
}

function readGrade() {
    rl.question("Enter grade: ", (grade) => {
        grades.push(Number(grade));
        count++;

        if (count < 5) {
            readGrade();
        }
        else {
            let totalPoints = 0;

            for (let grade of grades) {
                totalPoints += gradeToPoint(grade);
            }

            let gpa = totalPoints / grades.length;

            let standing = "";

            if (gpa >= 3.5) {
                standing = "Excellent";
            }
            else if (gpa >= 2.5) {
                standing = "Very Good";
            }
            else if (gpa >= 2.0) {
                standing = "Good";
            }
            else if (gpa >= 1.0) {
                standing = "Pass";
            }
            else {
                standing = "Fail";
            }

            console.log("GPA:", gpa);
            console.log("Standing:", standing);

            rl.close();
        }
    });
}

readGrade();

