Title: Student Score Ranking System

Problem Statement: 
Write a JavaScript program that reads the scores of 5 students.
The program should:
1. Store the scores in an array.
2. Sort the scores in descending order.
3. Display:
   - Highest Score
   - Lowest Score
   - Sorted Scores

Requirements:
1. Read 5 scores.
2. Store the scores in an array.
3. Sort the scores in descending order.
4. Display the highest score.
5. Display the lowest score.
6. Display the sorted scores.

سلم التصحيح:
Total: 10 marks

1. Input reading: 2 marks
2. Array usage: 2 marks
3. Sorting: 3 marks
4. Highest & Lowest: 2 marks
5. Correct output: 1 mark

الحل النموذجي:
const readline = require("readline");

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let scores = [];
let count = 0;

function readScore() {

    rl.question("Enter score: ", (score) => {

        scores.push(Number(score));
        count++;

        if (count < 5) {
            readScore();
        }
        else {

            scores.sort((a, b) => b - a);

            console.log("Highest Score:", scores[0]);
            console.log("Lowest Score:", scores[scores.length - 1]);

            console.log("Sorted Scores:");

            for (let score of scores) {
                console.log(score);
            }

            rl.close();
        }

    });

}

readScore();

