Title: Voting System

Problem Statement: 
Write a JavaScript program that reads the votes of 5 students.
Each student votes for one of the following candidates:
- A
- B
- C
The program should:
1. Store the votes in an array.
2. Count the number of votes for each candidate.
3. Display the number of votes for A, B, and C.
4. Display the winner.
5. If two or more candidates have the same highest number of votes, display:
Tie

Requirements:
1. Read 5 votes.
2. Store votes in an array.
3. Count votes for each candidate.
4. Determine the winner correctly.
5. Detect ties correctly.
6. Display all vote counts.
7. Display the correct result.

سلم التصحيح:
Total: 10 marks

1. Input reading: 2 marks
2. Array usage: 1 mark
3. Vote counting: 3 marks
4. Winner/Tie logic: 2 marks
5. Correct output: 1 mark
6. Code readability: 1 mark

الحل النموذجي:
const readline = require("readline");

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let votes = [];
let count = 0;

function readVote() {

    rl.question("Enter vote (A, B, or C): ", (vote) => {

        votes.push(vote.toUpperCase());
        count++;

        if (count < 5) {
            readVote();
        } else {

            let votesA = 0;
            let votesB = 0;
            let votesC = 0;

            for (let vote of votes) {
                if (vote === "A") {
                    votesA++;
                }
                else if (vote === "B") {
                    votesB++;
                }
                else if (vote === "C") {
                    votesC++;
                }
            }

            console.log("Votes for A:", votesA);
            console.log("Votes for B:", votesB);
            console.log("Votes for C:", votesC);

            if (
                votesA === votesB && votesA >= votesC ||
                votesA === votesC && votesA >= votesB ||
                votesB === votesC && votesB >= votesA
            ) {
                console.log("Tie");
            }
            else if (votesA > votesB && votesA > votesC) {
                console.log("Winner: A");
            }
            else if (votesB > votesA && votesB > votesC) {
                console.log("Winner: B");
            }
            else {
                console.log("Winner: C");
            }

            rl.close();
        }

    });

}

